// Umbrales configurables (variables de entorno de Node-RED; valores por defecto didacticos)
const U_ADV  = Number(env.get("UMBRAL_ADVERTENCIA")) || 28;
const U_CRIT = Number(env.get("UMBRAL_CRITICO"))     || 30;
const L_BAJA = Number(env.get("LUZ_BAJA_PCT"))       || 20;
const L_ALTA = Number(env.get("LUZ_ALTA_PCT"))       || 70;

const p   = msg.payload || {};
const dev = p.device_id || "desconocido";
const t = p.temp, h = p.hum, l = p.luz_pct;

// 1) VALIDACION
const errores = [];
if (typeof t !== "number" || !isFinite(t) || t < -40 || t > 80) errores.push("temp nula o fuera de rango (-40..80)");
if (h !== null && h !== undefined && (typeof h !== "number" || h < 0 || h > 100)) errores.push("humedad fuera de rango (0..100)");
if (typeof l !== "number" || l < 0 || l > 100) errores.push("luz_pct fuera de rango (0..100)");

if (errores.length) {
    node.warn("Lectura invalida descartada: " + errores.join("; "));
    return [null, { payload: [ { motivo: errores.join("; "), crudo: JSON.stringify(p) }, { device_id: dev } ] }, null, null];
}

// 2) CLASIFICACION
const estadoTemp = t >= U_CRIT ? "CRITICO" : (t >= U_ADV ? "ADVERTENCIA" : "NORMAL");
const codigo = { NORMAL: 0, ADVERTENCIA: 1, CRITICO: 2 }[estadoTemp];
const estadoLuz = l < L_BAJA ? "BAJA" : (l > L_ALTA ? "ALTA" : "NORMAL");

// 3) MEDICION (la marca de tiempo la asigna InfluxDB al recibir la escritura)
const campos = { temperatura: t, luz_pct: l, luz_raw: p.luz, seq: p.seq };
if (typeof h === "number") campos.humedad = h;
if (p.ts > 1700000000000) campos.latencia_ms = Date.now() - p.ts;   // solo si el ESP32 envio hora NTP valida

const msgAmb = { payload: [ campos, { device_id: dev, sala: "sala01", estado_temp: estadoTemp, estado_luz: estadoLuz } ] };
const msgEstado = { payload: [ { codigo: codigo, estado: estadoTemp }, { device_id: dev } ] };

// 4) ALERTA solo en TRANSICION (evita duplicar el evento en cada lectura critica)
const clave = "estado_prev_" + dev;
const prev = flow.get(clave);
flow.set(clave, estadoTemp);
let msgAlerta = null;
if (estadoTemp === "CRITICO" && prev !== "CRITICO") {
    msgAlerta = { payload: [
        { temperatura: t, mensaje: "Temperatura critica: " + t + " C (umbral " + U_CRIT + " C)" },
        { tipo: "temperatura_critica", severidad: "critica", device_id: dev } ] };
} else if (prev === "CRITICO" && estadoTemp !== "CRITICO") {
    msgAlerta = { payload: [
        { temperatura: t, mensaje: "Temperatura normalizada: " + t + " C" },
        { tipo: "temperatura_normalizada", severidad: "info", device_id: dev } ] };
}

return [msgAmb, null, msgAlerta, msgEstado];

// Se ejecuta cuando pasan 15 s sin telemetria (desconexion / perdida de mensajes)
node.warn("Sin datos de telemetria por mas de 15 s");
const dev = "esp32-sala01";
return [
  { payload: [ { codigo: 3, estado: "SIN_DATOS" }, { device_id: dev } ] },
  { payload: [ { mensaje: "Sin datos de telemetria por mas de 15 s" },
               { tipo: "sin_datos", severidad: "alta", device_id: dev } ] }
];

// LWT / estado del dispositivo: "online" | "offline"
const v = String(msg.payload).trim().toLowerCase();
return { payload: [ { estado: v }, { device_id: "esp32-sala01" } ] };
